INSERT INTO `sys_doc_help` VALUES ('35owMEqG1lUXhva2IBBelPnZspfqiqQG', '敏捷开发-系统构建', '开发主旨#\n自研低代码开发平台\n高质效构建中小型 MIS\n兼顾大型平台轻量化模块设计\n融合前沿技术与企业级实践\n重构高效开发范式', '<h3 style=\"text-align:start;text-indent:2em;\" id=\"开发主旨\" class=\"mt-10 mb-2 leading-7 text-xl title_3b154\"><strong><span style=\"color:#003ba5\">开发主旨</span></strong></h3><ul><li>自研低代码开发平台</li><li>高质效构建中小型 MIS</li><li>兼顾大型平台轻量化模块设计</li><li>融合前沿技术与企业级实践</li><li>重构高效开发范式</li></ul><h3 style=\"text-align:start;text-indent:2em;\" id=\"核心定位与技术基因\" class=\"mt-10 mb-2 leading-7 text-xl title_3b154\"><strong><span style=\"color:#b82727\">核心定位与技术基因</span></strong></h3><ul><li>敏捷开发引擎</li><ol><li>先管理好系统核心资产（功能和数据）事半功倍</li><li>构建“壳”系统和数据字典驱动底层能力</li><li>通过元数据定义模块元素进而转化为可执行功能</li><li>业务技术有效解耦大幅度提升开发质效并降低人员要求</li></ol></ul><p></p><ul><li>轻量化技术栈</li><ol><li>支持 Java主流语言</li><li>适配 MySQL等数据库</li><li>提供本地化部署与云端 SaaS 双模式</li><li>满足中小型企业成本敏感与灵活扩展需求</li><li>有效支撑国产化、特殊数据库等个性化要求</li></ol></ul><p></p><h3 style=\"text-align:start;text-indent:2em;\" id=\"开发范式与综合收益\" class=\"mt-10 mb-2 leading-7 text-xl title_3b154\">开发范式与综合收益</h3><ul><li><code>“壳”</code>系统支撑中小型MIS快速构建</li><ol><li>10%系统功能复用——微调</li><li>70%字典驱动功能——配置</li><li>20%个性化功能——独立开发</li><li>原型及PRD与可执行系统</li><li>高品质核心文档随系统高质效管控</li></ol></ul><p></p><ul><li>基于软件生命周期综合收益大幅度提升</li><ol><li>底层成本投入 &amp; 大技术升级：技术能力越强越可控</li><li>一次乘积效应：产品品质&amp;开发效率、功能优化&amp;可扩展性、高品质文档、人均质效……</li><li>二次乘积效应：多项目、长周期，收益更大。</li></ol></ul><p></p>', '# 开发主旨\n\n* 自研低代码开发平台\n* 高质效构建中小型 **MIS**\n* 兼顾大型平台轻量化模块设计\n* 融合前沿技术与企业级实践\n* 重构高效开发范式\n* 核心定位与技术基因\n\n# 敏捷开发引擎\n\n1. 先管理好系统核心资产（功能和数据）事半功倍\n2. 构建“壳”系统和数据字典驱动底层能力\n3. 通过元数据定义模块元素进而转化为可执行功能\n4. 业务技术有效解耦大幅度提升开发质效并降低人员要求\n5. 轻量化技术栈\n6. 支持 Java主流语言\n7. 适配 MySQL等数据库\n8. 提供本地化部署与云端 SaaS 双模式\n9. 满足中小型企业成本敏感与灵活扩展需求\n10. 有效支撑国产化、特殊数据库等个性化要求', 'A1010', '测试文档备注');
INSERT INTO `sys_doc_help` VALUES ('OREHHS0GUgMThUTEVaCfXLhvV3PVkKuN', '字典模块示例-进货明细', '该模块主要用于匹配出口货物的采购凭证（增值税专用发票）与出口报关单信息，通过计算进项税额与退税额的差额确定可退税款‌，其核心功能包括：\n‌数据匹配‌：将采购发票与出口报关单的商品名称、数量、金额等关键字段自动关联‌\n‌税额计算‌：根据征退税率差自动生成可退税额明细‌\n‌风险控制‌：通过系统校验发票真伪及合规性，防范骗税风险。‌', '<p><span style=\"font-size:20px\"><strong><span style=\"line-height:2\">一、进货明细模块的核心作用</span></strong></span></p><p><span style=\"line-height:2\">该模块主要用于匹配出口货物的采购凭证（增值税专用发票）与出口报关单信息，通过计算进项税额与退税额的差额确定可退税款‌，其核心功能包括：</span></p><ul><li><span style=\"line-height:2\">‌数据匹配‌：将采购发票与出口报关单的商品名称、数量、金额等关键字段自动关联‌</span></li><li><span style=\"line-height:2\">‌税额计算‌：根据征退税率差自动生成可退税额明细‌</span></li><li><span style=\"line-height:2\">‌风险控制‌：通过系统校验发票真伪及合规性，防范骗税风险‌</span></li></ul><p></p><p><span style=\"font-size:20px\"><strong><span style=\"line-height:2\">二、操作流程详解</span></strong></span></p><p><span style=\"line-height:2\"><strong>‌数据采集‌</strong></span></p><ul><li><span style=\"line-height:2\">通过电子税务局或&quot;单一窗口&quot;系统导入增值税专用发票信息（支持Excel批量导入或XML格式）‌</span></li><li><span style=\"line-height:2\">手动录入时需包含：发票代码、发票号码、开票日期、金额、税额等完整字段‌</span></li></ul><p><span style=\"line-height:2\"><strong>‌智能配单‌</strong></span></p><ul><li><span style=\"line-height:2\">系统提供三种配单方式：</span></li></ul><p style=\"text-indent:2em;\"><span style=\"line-height:2\">报关单逐项配单</span></p><p style=\"text-indent:2em;\"><span style=\"line-height:2\">发票逐项配单</span></p><p style=\"text-indent:2em;\"><span style=\"line-height:2\">商品品名分类配单‌</span></p><ul><li><span style=\"line-height:2\">支持连号发票批量匹配功能‌</span></li></ul><p><span style=\"line-height:2\"><strong>‌数据校验‌</strong></span></p><ul><li><span style=\"line-height:2\">自动检查发票状态（是否已认证、是否超期）</span></li><li><span style=\"line-height:2\">比对报关单与发票的商品编码一致性‌</span></li><li><span style=\"line-height:2\">生成疑点提示（如税率差异超限等）‌</span></li></ul><p></p><p><span style=\"font-size:20px\"><strong><span style=\"line-height:2\">三、特殊注意事项</span></strong></span></p><p><span style=\"line-height:2\">‌时效要求‌：采购发票需在出口报关单申报后次年4月增值税纳税申报期前完成认证‌</span></p><p><span style=\"line-height:2\">‌资料留存‌：需保存采购合同、付款凭证等原始单据备查‌</span></p><p><span style=\"line-height:2\">‌汇率处理‌：系统支持按出口日期自动匹配记账汇率‌</span></p><p><span style=\"line-height:2\">（注：视频组件展示外贸企业出口退税账务处理实操案例）</span></p><p></p>', '## 一、进货明细模块的核心作用\n\n该模块主要用于匹配出口货物的采购凭证（增值税专用发票）与出口报关单信息，通过计算进项税额与退税额的差额确定可退税款‌，其核心功能包括：\n* ‌数据匹配‌：将采购发票与出口报关单的商品名称、数量、金额等关键字段自动关联‌\n* ‌税额计算‌：根据征退税率差自动生成可退税额明细‌\n* ‌风险控制‌：通过系统校验发票真伪及合规性，防范骗税风险‌\n\n## 二、操作流程详解\n‌\n### 数据采集‌\n\n通过电子税务局或\"单一窗口\"系统导入增值税专用发票信息（支持Excel批量导入或XML格式）‌\n手动录入时需包含：发票代码、发票号码、开票日期、金额、税额等完整字段‌\n\n### ‌智能配单‌\n系统提供三种配单方式：\n关单逐项配单\n 发票逐项配单\n商品品名分类配单‌\n支持连号发票批量匹配功能‌\n\n### ‌数据校验‌\n* 自动检查发票状态（是否已认证、是否超期）\n* 比对报关单与发票的商品编码一致性‌\n* 生成疑点提示（如税率差异超限等）‌\n\n## 三、特殊注意事项\n* ‌时效要求‌：采购发票需在出口报关单申报后次年4月增值税纳税申报期前完成认证‌\n* ‌资料留存‌：需保存采购合同、付款凭证等原始单据备查‌\n* ‌汇率处理‌：系统支持按出口日期自动匹配记账汇率‌\n* （注：视频组件展示外贸企业出口退税账务处理实操案例）\n\n## 四、常见问题处理\n**‌发票信息缺失‌：可通过\"发票管理\"模块补录或重新导入‌\n‌商品编码不符‌：需在\"海关出口商品代码调整表\"中维护映射关系‌\n‌申报数据修改‌：**支持对已生成明细进行修改或删除操作', '1010', '测试备注进货明细');
